query queryDenyBypassNonAliased {
  updatePost(filter: { title: "*%.tile", body: { where: { title: "valid" } } }) {
    id
    title
    body
  }
}

query queryDenyBypassAliased {
  s: updatePost(filter: { title: "*%tile", body: { where: { title: "valid" } } }) {
    id
    title
    body
  }
}

query Introspection {
  updatePost {
    types {
      name
      kind
    }
    queryType {
      name
    }
    mutationType {
      name
    }
    subscriptionType {
      name
    }
  }
}

query FieldSuggestions {
  updatePost(id: "1") {
    __schema {
      queryType {
        fields {
          name
          type
        }
      }
      mutationType {
        fields {
          name
          type
        }
      }
    }
  }
}
